<?php require_once "config/database.php";require_once "includes/functions.php";$id=(int)($_GET["id"]??0);$st=$pdo->prepare("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=?");$st->execute([$id]);$p=$st->fetch();if(!$p)exit("Product not found");?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($p["name"])?></title><link rel="stylesheet" href="assets/css/style.css"></head><body><?php include "includes/navbar.php";?><main class="container page"><div class="detail"><div class="detail-art">JKTECH</div><div><span class="eyebrow"><?=e($p["brand"])?></span><h1><?=e($p["name"])?></h1><p><?=e($p["description"]??"Quality-checked reconditioned automotive part.")?></p><h2>Rs. <?=number_format($p["price"],2)?></h2><p>Stock: <?=$p["stock"]?> · Grade: <?=e($p["condition_grade"]??"B")?></p><form method="post" action="cart.php"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p["id"]?>"><input type="number" name="quantity" min="1" value="1"><button class="btn primary">Add to Cart</button></form></div></div></main></body></html>